using System;
using System.IO;
using Aspose.Pdf;
using Aspose.Pdf.Drawing;

class Program
{
    static void Main()
    {
        // Create the PDF containing a simple line graph and obtain its byte representation
        byte[] pdfBytes = CreatePdfWithGraph();

        // Example placeholder: output the size of the generated byte array
        Console.WriteLine($"PDF byte array length: {pdfBytes.Length}");
    }

    static byte[] CreatePdfWithGraph()
    {
        // MemoryStream will hold the PDF in memory for serialization
        using (MemoryStream ms = new MemoryStream())
        {
            // Create a new PDF document; wrapped in a using block for deterministic disposal
            using (Document doc = new Document())
            {
                // Add a single page to the document
                Page page = doc.Pages.Add();

                // Create a Graph container. The constructor now uses double values as required by the API.
                Graph graph = new Graph(500.0, 600.0);

                // OPTIONAL: add a light‑gray background rectangle to the graph area.
                // Use the correct Rectangle constructor (left, bottom, width, height).
                Aspose.Pdf.Drawing.Rectangle background = new Aspose.Pdf.Drawing.Rectangle(0f, 0f, 500f, 600f)
                {
                    GraphInfo = new GraphInfo
                    {
                        Color = Color.LightGray,
                        FillColor = Color.LightGray
                    }
                };
                graph.Shapes.Add(background);

                // Sample data for the graph (simple line chart)
                double[] xValues = { 0, 1, 2, 3, 4, 5 };
                double[] yValues = { 10, 20, 15, 30, 25, 35 };

                // Simple scaling factors to map data points to the graph area.
                // Origin (0,0) of the graph is placed at (50,550) in the page coordinate system.
                const float originX = 50f;
                const float originY = 550f;
                const float xScale = 80f;   // pixels per X unit
                const float yScale = 15f;   // pixels per Y unit

                // Draw X and Y axes
                Line xAxis = new Line(new float[] { originX, originY, originX + 400, originY })
                {
                    GraphInfo = new GraphInfo { Color = Color.Black, LineWidth = 1 }
                };
                graph.Shapes.Add(xAxis);

                Line yAxis = new Line(new float[] { originX, originY, originX, originY - 400 })
                {
                    GraphInfo = new GraphInfo { Color = Color.Black, LineWidth = 1 }
                };
                graph.Shapes.Add(yAxis);

                // Draw the data series as a set of connected lines
                for (int i = 0; i < xValues.Length - 1; i++)
                {
                    float x1 = originX + (float)(xValues[i] * xScale);
                    float y1 = originY - (float)(yValues[i] * yScale);
                    float x2 = originX + (float)(xValues[i + 1] * xScale);
                    float y2 = originY - (float)(yValues[i + 1] * yScale);

                    Line dataLine = new Line(new float[] { x1, y1, x2, y2 })
                    {
                        GraphInfo = new GraphInfo
                        {
                            Color = Color.Blue,
                            LineWidth = 2
                        }
                    };
                    graph.Shapes.Add(dataLine);
                }

                // Add the completed graph to the page's content
                page.Paragraphs.Add(graph);

                // Save the PDF into the memory stream (no file system I/O)
                doc.Save(ms);
            }

            // Return the PDF as a byte array for network transmission
            return ms.ToArray();
        }
    }
}
